body.raw:
{
  "warehouse_id": {
    "type": "string"
  },
  "remark": {
    "type": "string"
  },
  "lines": {
    "type": "array",
    "items": {
      "type": "object",
      "required": [
        "product_id",
        "qty"
      ],
      "properties": {
        "product_id": {
          "type": "string"
        },
        "qty": {
          "type": "string"
        },
        "unit_cost": {
          "type": "string"
        },
        "lot_no": {
          "type": "string",
          "description": "Optional lot number; when set, a product_lot row is created/topped-up."
        },
        "manufacturing_date": {
          "type": "string",
          "format": "date-time"
        },
        "expiry_date": {
          "type": "string",
          "format": "date-time"
        }
      }
    }
  }
}
